class Solution {
public:
    int splitNum(int num) {
        string d = to_string(num);
        sort(d.begin(), d.end());
        long long a = 0, b = 0;
        for (int i = 0; i < (int)d.size(); i++) {
            if (i % 2 == 0) a = a * 10 + (d[i] - '0');
            else b = b * 10 + (d[i] - '0');
        }
        return (int)(a + b);
    }
};

