var splitNum = function(num) {
    const d = String(num).split('').sort();
    let a = 0, b = 0;
    for (let i = 0; i < d.length; i++) {
        if (i % 2 === 0) a = a * 10 + (+d[i]);
        else b = b * 10 + (+d[i]);
    }
    return a + b;
};
